// Error codes of the API. The title is the message shown to the user: short, without technical words.
// "when" fills the catalogue of ERRORS.md, generated by "npm run docs".
// One code per case the front must tell apart: "detail" only adds precision, it never changes the meaning of the code.
export const ERRORS = {
  LL_VALIDATION_422: {
    status: 422,
    title: 'Certains champs sont invalides.',
    when: 'Corps absent, JSON illisible ou champ invalide (voir `errors`)',
  },
  LL_AUTH_401: { status: 401, title: 'Votre session a expiré, reconnectez-vous.', when: 'Token absent, invalide ou expiré' },
  LL_LOGIN_401: { status: 401, title: 'Email ou mot de passe incorrect.', when: 'Échec de connexion' },
  LL_AUTH_403: {
    status: 403,
    title: "Vous n'avez pas accès à ce contenu.",
    when: "Action sur le contenu d'un autre (ex. supprimer la publication d'un autre)",
  },
  LL_REPORT_403: {
    status: 403,
    title: 'Vous ne pouvez pas signaler votre propre publication.',
    when: 'Signalement de sa propre publication',
  },
  LL_POST_404: { status: 404, title: "Cette publication n'existe pas ou n'est plus disponible.", when: 'Publication inconnue' },
  LL_USER_404: { status: 404, title: "Cet utilisateur n'existe pas.", when: 'Utilisateur inconnu' },
  LL_ZONE_404: { status: 404, title: "Cette zone n'existe pas ou n'est pas encore ouverte.", when: 'Zone inconnue' },
  LL_EVENT_404: { status: 404, title: "Cet événement n'existe pas ou a été annulé.", when: 'Événement inconnu' },
  LL_EMAIL_409: { status: 409, title: 'Cet email est déjà utilisé.', when: 'Inscription avec un email existant' },
  LL_REPORT_409: { status: 409, title: 'Vous avez déjà signalé ce contenu.', when: 'Signalement en double' },
  LL_PROFILE_ZONE_409: {
    status: 409,
    title: 'Choisissez votre quartier dans votre profil pour continuer.',
    when: "Action qui demande un quartier (ex. créer un événement) depuis un compte qui n'en a pas",
  },
  LL_RATE_429: { status: 429, title: 'Trop de tentatives, réessayez dans un instant.', when: 'Limitation de débit' },
  LL_INTERNAL_500: {
    status: 500,
    title: 'Une erreur est survenue de notre côté. Réessayez.',
    when: 'Toute exception non prévue',
  },
};

// Codes that only exist in the front (no API response), listed in ERRORS.md
export const FRONT_ERRORS = {
  LL_NETWORK: { title: 'Connexion perdue. Vérifiez votre réseau.', when: "Côté front uniquement : l'API n'a pas répondu" },
};

export const ERROR_TYPE_BASE = 'https://localloop.dev/errors/';

// Expected error, turned into an application/problem+json response by withErrorHandler.
// throw new AppError('LL_POST_404') or new AppError('LL_VALIDATION_422', { errors: [...] })
export class AppError extends Error {
  constructor(code, { detail, errors } = {}) {
    const definition = ERRORS[code];
    if (!definition) throw new Error(`Unknown error code ${code}`);

    super(detail || definition.title);
    this.name = 'AppError';
    this.code = code;
    this.status = definition.status;
    this.title = definition.title;
    this.detail = detail;
    this.errors = errors;
  }
}

// Body of an error response (RFC 7807 + business code), see EPIC Error management
export function problemBody(error, { instance, traceId }) {
  return {
    type: ERROR_TYPE_BASE + error.code,
    title: error.title,
    status: error.status,
    code: error.code,
    detail: error.detail || error.title,
    instance,
    traceId,
    ...(error.errors && { errors: error.errors }),
  };
}
